<script setup lang="ts">
import { t } from '../../i18n';
import type { ArticleEvidence } from './articleMetadata';
const props=defineProps<{modelValue?:ArticleEvidence[]}>();
const emit=defineEmits<{'update:modelValue':[value:ArticleEvidence[]]}>();
function add(){emit('update:modelValue',[...(props.modelValue??[]),{source_kind:'main_pdf',quoted_text:'',page_number:1}]);}
function remove(index:number){emit('update:modelValue',(props.modelValue??[]).filter((_,i)=>i!==index));}
</script>
<template><details class="evidence-editor" data-article-evidence-editor><summary>{{t('原文摘录')}} · {{modelValue?.length??0}}</summary><fieldset v-for="(entry,index) in modelValue" :key="index"><legend>{{t('证据')}} {{index+1}}</legend><label class="form-field">{{t('来源类型')}}<select v-model="entry.source_kind" @change="entry.bbox=null"><option value="main_pdf">{{t('主文')}}</option><option value="supplement">{{t('补充材料')}}</option><option value="external">{{t('外部数据库／来源')}}</option></select></label><label class="form-field">{{t('原文摘录')}}<textarea v-model="entry.quoted_text" required maxlength="6000" rows="4" data-quote-input></textarea></label><label v-if="entry.source_kind!=='external'" class="form-field">{{t('PDF 页码')}}<input v-model.number="entry.page_number" @change="entry.bbox=null" type="number" min="1" required></label><label class="form-field">{{t('原文位置／材料名称')}}<input v-model="entry.locator" @change="entry.locator=entry.locator||null" :required="entry.source_kind==='supplement'" maxlength="1000"></label><label class="form-field">{{t('来源链接')}}<input v-model="entry.source_url" type="url" pattern="https?://.+" :required="entry.source_kind==='external'" maxlength="2000" @change="entry.source_url=entry.source_url||null"></label><details><summary>{{t('原图定位')}}</summary><label class="form-field">PDF SHA-256<input v-model="entry.source_sha256" pattern="[0-9a-f]{64}" maxlength="64" @change="entry.source_sha256=entry.source_sha256||null;entry.bbox=null"></label><div v-if="entry.bbox" class="bbox-fields"><label v-for="key in (['x','y','width','height'] as const)" :key="key">{{key}}<input v-model.number="entry.bbox[key]" type="number" min="0" max="1" step="any" required></label><button type="button" @click="entry.bbox=null">{{t('清除原图定位')}}</button></div></details><button type="button" class="button-quiet" @click="remove(index)">{{t('删除')}}</button></fieldset><button type="button" class="button-secondary" data-add-quote @click="add">{{t('添加原文摘录')}}</button></details></template>
<style scoped>.evidence-editor{margin:.6rem 0}.evidence-editor fieldset{min-width:0;margin:.6rem 0;padding:.6rem}.form-field{margin:.5rem 0}textarea{width:100%;box-sizing:border-box}.bbox-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.5rem}</style>
